  tags_json = '["engineering","programmer","data","ai","ml","evaluation","official","commercial","zh-cn"]'::jsonb,
  updated_at = TIMESTAMPTZ '2026-11-03T00:00:00+08:00'
WHERE tenant_id = 100001 AND agent_id = 'agent.programmer.data.ai';

